(function (global) {
  'use strict';

  var SESSION_KEY = 'ezy_member_session';
  var AUTH_EVENT = 'ezy:auth';
  var PUBLIC_CONFIG_KEY = 'Ezycore_PublicConfig';
  var fbPromise = null;
  var RESOLVED = null;

  /* ---------- Config accessors (dinamis setelah discovery) ---------- */
  function currentConfig() {
    return RESOLVED || global.EZY_CONFIG || {};
  }
  function getFirebaseCfg() {
    var cfg = currentConfig();
    return cfg.firebase || null;
  }
  function getGasUrl() {
    var g = currentConfig().gas;
    return (g && g.url) || '';
  }
  function getGasFn() {
    var g = currentConfig().gas;
    return (g && g.function) || 'proxy';
  }

  /* ---------- Session ---------- */
  function getSession() {
    try { return JSON.parse(global.localStorage.getItem(SESSION_KEY) || 'null'); }
    catch (e) { return null; }
  }
  function setSession(u) {
    try { global.localStorage.setItem(SESSION_KEY, JSON.stringify(u)); } catch (e) {}
    notify();
  }
  function clearSession() {
    try { global.localStorage.removeItem(SESSION_KEY); } catch (e) {}
    notify();
  }
  function isLoggedIn() {
    var s = getSession();
    return !!(s && s.email);
  }
  function notify() {
    try { global.dispatchEvent(new global.Event(AUTH_EVENT)); } catch (e) {}
  }

  /* ---------- Firebase (lazy loader) ---------- */
  function ensureFirebase() {
    if (fbPromise) return fbPromise;
    if (!getFirebaseCfg()) {
      fbPromise = Promise.resolve(null);
      return fbPromise;
    }
    fbPromise = new Promise(function (resolve, reject) {
      if (global.firebase && global.firebase.apps && global.firebase.apps.length) {
        return resolve(global.firebase);
      }
      var srcs = [
        'https://www.gstatic.com/firebasejs/11.6.0/firebase-app-compat.js',
        'https://www.gstatic.com/firebasejs/11.6.0/firebase-auth-compat.js'
      ];
      var i = 0;
      (function next() {
        if (i >= srcs.length) {
          try { global.firebase.initializeApp(getFirebaseCfg()); return resolve(global.firebase); }
          catch (e) { return reject(e); }
        }
        var s = document.createElement('script');
        s.src = srcs[i++];
        s.onload = next;
        s.onerror = function () { reject(new Error('Gagal memuat Firebase SDK: ' + s.src)); };
        document.head.appendChild(s);
      })();
    });
    return fbPromise;
  }

  function mockDelay() {
    return new Promise(function (r) { setTimeout(r, 600); });
  }
  function buildSession(u) {
    return {
      uid: u.uid || '',
      email: u.email || '',
      displayName: u.displayName || '',
      photoURL: u.photoURL || '',
      loginAt: new Date().toISOString()
    };
  }

  /* ---------- Auth API ---------- */
  function signIn(email, password) {
    return ensureFirebase().then(function (fb) {
      if (fb) {
        return fb.auth().signInWithEmailAndPassword(email, password).then(function (cred) {
          var s = buildSession(cred.user);
          setSession(s);
          return s;
        });
      }
      return mockDelay().then(function () {
        var s = { email: email, loginAt: new Date().toISOString() };
        setSession(s);
        return s;
      });
    });
  }

  function register(email, password) {
    return ensureFirebase().then(function (fb) {
      if (fb) {
        return fb.auth().createUserWithEmailAndPassword(email, password).then(function (cred) {
          var s = buildSession(cred.user);
          setSession(s);
          return s;
        });
      }
      return mockDelay().then(function () {
        var s = { email: email, loginAt: new Date().toISOString() };
        setSession(s);
        return s;
      });
    });
  }

  function resetPassword(email) {
    return ensureFirebase().then(function (fb) {
      if (fb) return fb.auth().sendPasswordResetEmail(email);
      return mockDelay();
    });
  }

  function signOut() {
    return ensureFirebase().then(function (fb) {
      if (fb && fb.auth().currentUser) return fb.auth().signOut();
    }).then(function () {
      clearSession();
    }).catch(function () {
      clearSession();
    });
  }

  function getToken() {
    return ensureFirebase().then(function (fb) {
      if (fb && fb.auth().currentUser) return fb.auth().currentUser.getIdToken();
      var s = getSession();
      return s ? (s.uid || s.email || '') : '';
    });
  }

  function onAuthChange(cb) {
    ensureFirebase().then(function (fb) {
      if (fb) {
        fb.auth().onAuthStateChanged(function (u) {
          if (u) { cb(buildSession(u)); }
          else { clearSession(); cb(null); }
        });
      }
    });
    global.addEventListener('storage', function () { cb(getSession()); });
    global.addEventListener(AUTH_EVENT, function () { cb(getSession()); });
  }

  /* ---------- GAS proxy (Firestore / data) ---------- */
  function callGas(fn, payload) {
    var url = getGasUrl();
    if (!url) return Promise.reject(new Error('EZY_CONFIG.gas.url belum diatur.'));
    var body = Object.assign({ action: fn }, payload || {});
    var cfg = currentConfig();
    if (cfg.blogId) body.blogId = cfg.blogId;
    if (cfg.siteKey) body.siteKey = cfg.siteKey;
    return fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'text/plain' },
      body: JSON.stringify(body)
    }).then(function (r) {
      return r.text();
    }).then(function (text) {
      try { return JSON.parse(text); }
      catch (e) { throw new Error('Respons GAS tidak valid.'); }
    });
  }

  function saveData(path, data) {
    return callGas(getGasFn(), { op: 'save', path: path, data: data }).then(function (r) { notify(); return r; });
  }
  function getData(path) {
    return callGas(getGasFn(), { op: 'get', path: path });
  }
  function deleteData(path) {
    return callGas(getGasFn(), { op: 'delete', path: path }).then(function (r) { notify(); return r; });
  }

  /* ---------- EzyCore config discovery ---------- */
  function decodeB64(s) {
    try {
      var t = String(s).replace(/-/g, '+').replace(/_/g, '/');
      while (t.length % 4) { t += '='; }
      return atob(t);
    } catch (e) { return ''; }
  }
  function extractConfig(html) {
    if (!html) return null;
    var m = html.match(/data-config=["']([^"']+)["']/)
      || html.match(/data-config=&quot;([^&]+)&quot;/)
      || html.match(/data-ezy-config=["']([^"']+)["']/)
      || html.match(/<meta[^>]+name=["']ezy-config["'][^>]*content=["']([^"']+)["']/);
    var b64 = m ? m[1] : null;
    if (!b64) return null;
    var text = decodeB64(b64);
    try {
      var obj = JSON.parse(text);
      return obj && typeof obj === 'object' ? obj : null;
    } catch (e) { return null; }
  }
  function matchConfigTitle(t) {
    if (!t) return false;
    var n = String(t).toLowerCase().replace(/\s+/g, ' ').trim();
    return n === 'ezycore system configuration' || n.indexOf('ezycore system configuration') !== -1;
  }
  function parseFeed(data) {
    var entries = (data && data.feed && data.feed.entry) || [];
    for (var i = 0; i < entries.length; i++) {
      var e = entries[i];
      if (matchConfigTitle(e.title && e.title.$t)) {
        var cfg = extractConfig((e.content && e.content.$t) || '');
        if (cfg) return cfg;
      }
    }
    return null;
  }
  function readBin() {
    var bin = document.getElementById('ezy-jsonld-bin');
    if (bin && bin.textContent.trim()) {
      try {
        var obj = JSON.parse(decodeB64(bin.textContent.trim()));
        return obj && typeof obj === 'object' ? obj : null;
      } catch (e) {}
    }
    return null;
  }
  function readLocalStorage() {
    var out = {};
    try {
      var raw = global.localStorage.getItem(PUBLIC_CONFIG_KEY);
      var cached = raw ? JSON.parse(raw) : {};
      out.siteKey = cached.siteKey || '';
      out.webAppUrl = cached.webAppUrl || '';
      out.firebaseApiKey = cached.firebaseApiKey || '';
      out.projectId = cached.projectId || '';
      out.blogId = cached.blogId || '';
      if (!out.siteKey) out.siteKey = global.localStorage.getItem('Ezycore_SiteKey') || '';
    } catch (e) {}
    return (out.webAppUrl || (out.firebaseApiKey && out.projectId)) ? out : null;
  }
  function discoverViaFeed() {
    var urls = [
      '/feeds/pages/default?alt=json',
      '/feeds/posts/default?alt=json&max-results=500'
    ];
    var chain = Promise.resolve(null);
    urls.forEach(function (u) {
      chain = chain.then(function (found) {
        if (found) return found;
        return fetch(u)
          .then(function (res) { return res.json(); })
          .then(parseFeed)
          .catch(function () { return null; });
      });
    });
    return chain;
  }
  function cacheDiscovered(d) {
    if (!d) return;
    try {
      global.localStorage.setItem(PUBLIC_CONFIG_KEY, JSON.stringify({
        siteKey: d.siteKey || '',
        webAppUrl: d.webappUrl || d.webAppUrl || '',
        firebaseApiKey: d.firebaseApiKey || '',
        projectId: d.projectId || '',
        blogId: d.blogId || ''
      }));
      if (d.siteKey) global.localStorage.setItem('Ezycore_SiteKey', d.siteKey);
    } catch (e) {}
  }
  function toConfig(d) {
    d = d || {};
    var apiKey = d.firebaseApiKey || '';
    var projectId = d.projectId || '';
    var webAppUrl = d.webappUrl || d.webAppUrl || '';
    return {
      firebase: (apiKey || projectId) ? {
        apiKey: apiKey,
        projectId: projectId,
        authDomain: projectId ? projectId + '.firebaseapp.com' : ''
      } : null,
      gas: webAppUrl ? { url: webAppUrl, function: 'proxy' } : null,
      blogId: d.blogId || '',
      siteKey: d.siteKey || ''
    };
  }
  var readyResolve = null;
  var CONFIG_READY = new Promise(function (res) { readyResolve = res; });
  function finalize(cfg) {
    cfg = cfg || {};
    RESOLVED = cfg;
    global.EZY_CONFIG = cfg;
    var hasFirebase = !!(cfg.firebase && cfg.firebase.apiKey);
    var hasGas = !!(cfg.gas && cfg.gas.url);
    global.EZY_CONFIG_MISSING = !(hasFirebase || hasGas);
    console.log('[EzyBridge] Discovery selesai. EZY_CONFIG_MISSING =', global.EZY_CONFIG_MISSING);
    try { global.dispatchEvent(new global.CustomEvent('ezy-config-ready', { detail: cfg })); } catch (e) {}
    try { if (readyResolve) readyResolve(cfg); } catch (e) {}
  }
  global.EZY_CONFIG_READY = CONFIG_READY;
  function manualConfigured(manual) {
    if (!manual) return false;
    return !!((manual.firebase && manual.firebase.apiKey) || (manual.gas && manual.gas.url));
  }
  function initDiscovery() {
    console.log('[EzyBridge] Discovery konfigurasi dimulai...');
    var manual = global.EZY_CONFIG;
    if (manualConfigured(manual)) {
      console.log('[EzyBridge] Discovery OK (manual EZY_CONFIG di head).');
      finalize(manual);
      return;
    }
    var discovered = readBin() || readLocalStorage();
    if (discovered) {
      console.log('[EzyBridge] Discovery OK (bin/localStorage).');
      cacheDiscovered(discovered);
      finalize(toConfig(discovered));
      return;
    }
    discoverViaFeed().then(function (d) {
      if (d) {
        console.log('[EzyBridge] Discovery OK (Blogger Feed).');
        cacheDiscovered(d);
      } else {
        console.warn('[EzyBridge] Discovery GAGAL: halaman "EzyCore System Configuration" tidak ditemukan / data-config tidak valid.');
      }
      finalize(toConfig(d));
    });
  }
  initDiscovery();

  /* ---------- Ekspor API ---------- */
  global.ezyBridge = {
    config: currentConfig,
    getSession: getSession,
    setSession: setSession,
    clearSession: clearSession,
    isLoggedIn: isLoggedIn,
    ensureFirebase: ensureFirebase,
    signIn: signIn,
    register: register,
    resetPassword: resetPassword,
    signOut: signOut,
    getToken: getToken,
    onAuthChange: onAuthChange,
    callGas: callGas,
    saveData: saveData,
    getData: getData,
    deleteData: deleteData
  };
})(window);
